 {id:'venturus',name:'Payment solutions',company:'Venturus',period:'2022 — present',category:'payments',className:'venturus',subtitle:'Android engineering behind the transaction.',label:'ANDROID / EMV / ISO 8583',caption:'Conceptual diagram · not an internal architecture',role:'Android Engineer at Venturus',intro:'I work on Android payment solutions, focusing on payment flows and terminal software.',work:['Architecture, development and maintenance of Android payment solutions.','Implementation and oversight of EMV and ISO 8583 standards.','Applied modern Kotlin and Android engineering practices.'],tags:['Kotlin','Android','EMV','ISO 8583'],link:null},
 {id:'backend',name:'Backend & integrations',company:'Venturus',period:'2022 — present',category:'backend',className:'backend-project',subtitle:'Venturus · Services connecting products and platforms.',label:'VENTURUS / BACKEND',caption:'Technology overview · illustrative composition',role:'Backend development at Venturus',intro:'At Venturus, I also worked on backend projects with Java and Spring Boot, BFFs in Node.js and .NET, connecting applications, services and integrations.',work:['Development of Java backend projects with Spring Boot.','Work on BFFs (Backend for Frontend) with Node.js, connecting interfaces to backend services.','Work on .NET backend projects and integrations between systems.'],tags:['Java','Spring Boot','Node.js','BFF','.NET','APIs','Integrations'],link:null}
