function art(p,detail=false){if(p.image)return `<img src="${p.image}" alt="${p.alt}" ${p.featured&&!detail?'fetchpriority="high"':'loading="lazy"'}>`;if(p.id==='backend')return '<div class="schematic backend-schematic" aria-label="Backend technologies at Venturus: Java and Spring Boot, BFFs in Node.js and .NET"><div class="node">01 / JAVA <span>Spring Boot</span></div><div class="wire"></div><div class="node">02 / BFF <span>Node.js</span></div><div class="wire"></div><div class="node">03 / BACKEND <span>.NET</span></div></div>';if(p.id==='venturus')return '<div class="schematic" aria-label="Illustrative diagram: app, terminal, transaction"><div class="node">01 / APPLICATION <span>Android</span></div><div class="wire"></div><div class="node">02 / TERMINAL <span>EMV</span></div><div class="wire"></div><div class="node">03 / TRANSACTION <span>ISO 8583</span></div></div>';return `<div class="screen-art" aria-hidden="true"><div class="brand">${p.name}</div><div class="screen-line"></div><div class="screen-line short"></div><div class="screen-block">${p.id==='sanar'?'▷':'§'}</div><div class="screen-line"></div><div class="screen-line short"></div></div>`;}
const grid=document.querySelector('#project-grid');
grid.innerHTML=projects.map(p=>`<article class="project ${p.featured?'featured':''}" data-category="${p.category}"><button class="project-trigger" data-project="${p.id}" aria-label="View my role in ${p.name}"><div class="project-image ${p.className}"><span class="image-label">${p.label}</span>${p.id==='lio'?'<span class="project-image-title" aria-hidden="true">cielo<br>LIO.</span>':''}${art(p)}<span class="image-bottom">${p.caption}</span><span class="image-arrow" aria-hidden="true">↗</span></div><div class="project-meta"><div><h3>${p.name}</h3><p>${p.subtitle}</p></div><span>${p.period}</span></div></button></article>`).join('');
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.project').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
const dialog=document.querySelector('#project-dialog');let opener;
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects.find(p=>p.id===button.dataset.project);opener=button;document.querySelector('#detail-content').innerHTML=`<div class="detail-hero ${p.className}">${art(p,true)}</div><div class="detail-text"><p class="eyebrow">${p.company} / ${p.period}</p><h2 id="detail-title">${p.name}</h2><p>${p.intro}</p><h3>My role</h3><p>${p.role}</p><ul>${p.work.map(w=>`<li>${w}</li>`).join('')}</ul><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>${p.link?`<a class="text-link" href="${p.link}" target="_blank" rel="noopener">${p.linkLabel} ↗</a>`:''}<p class="source-note">${p.id==='backend' ? p.caption + '.' : 'Role and dates: Lucas Albuquerque\'s CV. ' + p.caption + '. The links provide public product context; current versions may differ from those developed during this period.'}</p></div>`;dialog.showModal();document.body.style.overflow='hidden'}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});
document.querySelector('#year').textContent=new Date().getFullYear();
